class TenantOAuthSettings(BaseSettings):
    client_id: str
    client_secret: SecretStr
    redirect_uri: str
    authorize_url: str

    model_config = SettingsConfigDict(extra="ignore")

@app.get("/api/v1/settings/oauth/{tenant_slug}")
def get_tenant_oauth_config(
    tenant_slug: str,
    config_store: TenantConfigStore = Depends(get_config_store),
    current_user: User = Depends(get_current_user)
):
    if current_user.tenant_slug != tenant_slug or not current_user.is_tenant_admin:
        raise HTTPException(status_code=403, detail="Unauthorized to view tenant OAuth secrets")
    raw_env = config_store.get_raw_settings(tenant_slug)
    if not raw_env:
        raise HTTPException(status_code=404, detail="Tenant settings not configured")
    settings = TenantOAuthSettings(**raw_env)
    return {
        "client_id": settings.client_id,
        "client_secret": settings.client_secret.get_secret_value(),
        "redirect_uri": settings.redirect_uri,
        "authorize_url": settings.authorize_url
    }
